def armstrong_number(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sum_digits = 0
    num_digits = len(str(n))
    for digit in str(n):
        sum_digits += int(digit) ** num_digits
    return sum_digits == n

def tuple_modulo(t1, t2):
    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise ValueError("Both arguments must be tuples")

    if len(t1) != len(t2):
        raise ValueError("Tuples must have the same length")

    for i in range(len(t1)):
        if not isinstance(t1[i], int) or not isinstance(t2[i], int):
            raise ValueError("All elements must be integers")

    for b in t2:
        if b == 0:
            raise ValueError("Modulo by zero is not allowed")

    return tuple(a % b for a, b in zip(t1, t2))

